const SYSTEMS=[{name:"Musculoskeletal",icon:"🦴",tint:"#f4e5d9",color:"#bd8060"},{name:"Neurology",icon:"🧠",tint:"#ece9f5",color:"#8879ae"},{name:"Cardiorespiratory",icon:"🫀",tint:"#f7e7e6",color:"#bd7772"},{name:"Sports & Exercise",icon:"🏃",tint:"#e8efdc",color:"#81995f"},{name:"Paediatrics",icon:"🧸",tint:"#f7efdc",color:"#b69a55"},{name:"Women's Health",icon:"🌷",tint:"#f5e8ee",color:"#bd829d"},{name:"Geriatrics",icon:"🌿",tint:"#e5eee8",color:"#6c9a7e"},{name:"Other",icon:"📚",tint:"#e9edf0",color:"#8095a2"}];
const SEED=[
{id:"acl",title:"Anterior Cruciate Ligament (ACL) Injury",system:"Musculoskeletal",summary:"A common knee ligament injury involving instability, swelling and difficulty with pivoting movements.",definition:"An injury to the anterior cruciate ligament, which helps control anterior translation and rotational stability of the tibia relative to the femur.",causes:"Non-contact pivoting, sudden deceleration, awkward landing, or direct trauma.",signs:"A pop at injury, rapid swelling (haemarthrosis), giving-way episodes, reduced range of motion and difficulty weight-bearing.",assessment:"History and mechanism; observe swelling and gait; assess range of motion, Lachman, anterior drawer and pivot shift as appropriate. Consider imaging and referral based on clinical findings.",management:"Individualised rehabilitation: manage swelling, restore extension and flexion, regain quadriceps strength, progressive neuromuscular and landing training. Surgical decisions are individual and specialist-led.",complications:"Persistent instability, associated meniscal or chondral injury, reduced activity and increased risk of later osteoarthritis.",bookmarked:true},
{id:"stroke",title:"Stroke",system:"Neurology",summary:"Acute neurological dysfunction caused by interruption of cerebral blood flow or bleeding.",definition:"A sudden focal neurological deficit due to cerebral infarction or intracerebral haemorrhage.",causes:"Ischaemic stroke from arterial occlusion; haemorrhagic stroke from vessel rupture. Risk factors include hypertension, atrial fibrillation, diabetes and smoking.",signs:"Facial weakness, arm weakness, speech or visual disturbance, sensory loss, ataxia or sudden severe headache. Presentation depends on lesion location.",assessment:"Recognise FAST symptoms and activate emergency stroke pathway immediately. Medical assessment and brain imaging distinguish stroke type. Rehabilitation assessment includes motor, sensory, balance, cognition, communication and function.",management:"Time-critical emergency medical care. Physiotherapy focuses on safe early mobilisation when appropriate, task-specific practice, strength, balance, gait, upper-limb function and prevention of complications.",complications:"Dysphagia, aspiration, falls, contracture, shoulder pain, spasticity, depression and recurrent stroke."},
{id:"copd",title:"Chronic Obstructive Pulmonary Disease",system:"Cardiorespiratory",summary:"A chronic respiratory condition with persistent airflow limitation and respiratory symptoms.",definition:"A heterogeneous lung condition characterised by chronic respiratory symptoms due to airway and/or alveolar abnormalities that cause persistent, often progressive airflow obstruction.",causes:"Tobacco smoke, biomass exposure, occupational dusts and fumes, air pollution and genetic factors such as alpha-1 antitrypsin deficiency.",signs:"Progressive breathlessness, chronic cough, sputum production, wheeze, reduced exercise tolerance and exacerbations.",assessment:"Clinical history, spirometry (post-bronchodilator FEV1/FVC below 0.70 supports diagnosis), symptom burden, exacerbation history, oxygenation and functional capacity.",management:"Smoking cessation, inhaled therapies prescribed by a clinician, vaccinations, pulmonary rehabilitation, exercise training, breathing strategies and self-management education.",complications:"Acute exacerbations, respiratory failure, pulmonary hypertension, cor pulmonale, anxiety, frailty and reduced quality of life."},
{id:"oa-knee",title:"Knee Osteoarthritis",system:"Musculoskeletal",summary:"A whole-joint disorder commonly presenting with pain, stiffness and reduced function.",definition:"A chronic joint condition involving changes to cartilage, subchondral bone, synovium and surrounding structures.",causes:"Ageing, previous joint injury, obesity, genetic factors, altered joint mechanics and occupational or sporting loading.",signs:"Activity-related pain, brief morning stiffness, crepitus, reduced range of motion, bony enlargement and functional limitation.",assessment:"History, functional goals, gait, range of motion, strength and relevant red flags. Diagnosis is often clinical; imaging is not routinely required in typical presentations.",management:"Education, tailored strengthening and aerobic exercise, weight management where relevant, pacing and shared decision-making about analgesia or surgical referral.",complications:"Reduced mobility, muscle weakness, sleep disturbance, falls risk and reduced participation."},
{id:"low-back",title:"Non-specific Low Back Pain",system:"Musculoskeletal",summary:"Pain in the lumbar region without a clearly identifiable specific underlying pathology.",definition:"Low back pain for which no specific structural cause can be confidently identified after appropriate assessment.",causes:"Often multifactorial, involving physical, psychological and social contributors. A single tissue source is frequently not identifiable.",signs:"Variable lumbar pain, movement sensitivity and functional limitation. Screen for red flags and neurological symptoms.",assessment:"History, functional impact, neurological screen when indicated, red-flag screening and assessment of movement and patient goals.",management:"Reassurance, staying active, graded exercise, self-management, and psychologically informed care where appropriate. Tailor treatment to the person.",complications:"Persistent pain, fear avoidance, reduced activity, sleep and mood disturbance."},
{id:"parkinsons",title:"Parkinson's Disease",system:"Neurology",summary:"A progressive neurological disorder affecting movement and non-motor function.",definition:"A neurodegenerative condition associated with loss of dopaminergic neurons, producing characteristic motor and non-motor features.",causes:"Usually idiopathic and multifactorial; age and genetic and environmental factors may contribute.",signs:"Bradykinesia with rigidity and/or resting tremor, postural instability, freezing, reduced arm swing, sleep, mood and autonomic symptoms.",assessment:"Medical diagnosis; physiotherapy evaluates gait, balance, transfers, falls, posture, strength, dual-task ability and functional goals.",management:"Amplitude-based exercise, gait cueing, balance and strength training, aerobic activity, falls prevention and multidisciplinary care. Coordinate with medication timing.",complications:"Falls, freezing, dysphagia, communication changes, cognitive impairment and loss of independence."}
];
let db=loadDB(),view="library",activeId=null,filterSystem=null,search="",flashIndex=0,flashRevealed=false,flashDeck=[],drawing=false,ctx=null,canvasHistory=[];
function loadDB(){try{const x=JSON.parse(localStorage.getItem("physioAtlasDB"));if(x&&Array.isArray(x.conditions)){x.articles=Array.isArray(x.articles)?x.articles:[];x.sketches=Array.isArray(x.sketches)?x.sketches:[];return x}return{conditions:SEED.map(x=>({...x,images:[],notes:"",cards:[],created:Date.now()})),sketches:[],articles:[]}}catch{return{conditions:SEED.map(x=>({...x,images:[],notes:"",cards:[]})),sketches:[],articles:[]}}}
function save(){localStorage.setItem("physioAtlasDB",JSON.stringify(db));updateStats()}
function esc(s=""){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function toast(s){const t=document.getElementById("toast");t.textContent=s;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2200)}
function updateStats(){document.getElementById("sidebarStats").textContent=db.conditions.length+" conditions · "+(db.articles||[]).length+" critiques";document.getElementById("dueCount").textContent=db.conditions.reduce((n,c)=>n+(c.cards||[]).length,0)}
function systemNav(){document.getElementById("systemNav").innerHTML=SYSTEMS.map(s=>`<button class="system-link ${filterSystem===s.name?"active":""}" data-system="${s.name}"><i class="system-dot" style="--dot:${s.color}"></i>${s.name}</button>`).join("")}
function setView(v){view=v;activeId=null;filterSystem=null;document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.view===v));document.getElementById("crumb").textContent=v.toUpperCase();systemNav();render()}
function render(){const root=document.getElementById("content");if(activeId){renderEditor(root);return}if(view==="flashcards")return renderFlash(root);if(view==="canvas")return renderSketch(root);if(view==="settings")return renderSettings(root);if(view==="articles")return renderArticles(root);if(view==="bookmarks")return renderLibrary(root,true);renderLibrary(root,false)}
function renderLibrary(root,bookmarks){let items=db.conditions.filter(c=>(!bookmarks||c.bookmarked)&&(!filterSystem||c.system===filterSystem)&&(!search||(c.title+" "+c.summary+" "+c.system).toLowerCase().includes(search.toLowerCase())));let selected=filterSystem|| (bookmarks?"BOOKMARKS":"MY LIBRARY");document.getElementById("crumb").textContent=selected.toUpperCase();root.innerHTML=`<div class="hero"><div><div class="eyebrow">YOUR KNOWLEDGE, IN ONE PLACE</div><h1>${bookmarks?"Your bookmarks":filterSystem||"A textbook that grows with you."}</h1><p>${bookmarks?"The conditions you want to revisit.":filterSystem?"Explore your "+filterSystem.toLowerCase()+" notes and learning cards.":"Build your own visual atlas of conditions, concepts and clinical knowledge."}</p></div><div class="hero-art">🩺</div></div>
<div class="stats"><div class="stat"><span>CONDITIONS IN YOUR LIBRARY</span><strong>${db.conditions.length}</strong><em>↑ Your personal collection</em></div><div class="stat"><span>BODY SYSTEMS</span><strong>${new Set(db.conditions.map(c=>c.system)).size}</strong><em>Organise your learning</em></div><div class="stat"><span>FLASHCARDS CREATED</span><strong>${db.conditions.reduce((n,c)=>n+(c.cards||[]).length,0)}</strong><em>Active recall practice</em></div><div class="stat"><span>BOOKMARKED</span><strong>${db.conditions.filter(c=>c.bookmarked).length}</strong><em>Saved for revision</em></div></div>
${!filterSystem&&!bookmarks&&!search?`<div class="section-head"><h2>Explore body systems</h2><span class="eyebrow">08 COLLECTIONS</span></div><div class="system-grid">${SYSTEMS.map(s=>`<button class="system-card" data-system="${s.name}" style="--tint:${s.tint}"><span class="system-icon">${s.icon}</span><b>${s.name}</b><small>${db.conditions.filter(c=>c.system===s.name).length} conditions</small></button>`).join("")}</div>`:""}
<div class="section-head"><h2>${search?"Search results":bookmarks?"Saved conditions":"Your conditions"}</h2><div class="toolbar-row"><button class="text-button" id="addTemplates">＋ Add 12 starter chapters</button><button class="text-button" id="addMoreTopics">＋ Add 29 more topics</button><button class="text-button" id="addConditionInline">＋ Add a condition</button></div></div>
${items.length?`<div class="condition-grid">${items.map(c=>`<button class="condition-card" data-open="${c.id}"><span class="tag">${esc(c.system)}</span><h3>${esc(c.title)}</h3><p>${esc(c.summary||"Add a short overview to this condition.")}</p><div class="card-meta"><span>${(c.images||[]).length} images · ${(c.cards||[]).length} cards</span><span>OPEN NOTES ↗</span></div></button>`).join("")}</div>`:`<div class="empty"><b>${bookmarks?"No bookmarks yet":search?"No matching conditions":"Your next chapter starts here."}</b>${search?"Try another search term.":"Add a condition and start building your personal textbook."}</div>`}`;root.querySelectorAll("[data-system]").forEach(b=>b.onclick=()=>{filterSystem=b.dataset.system;view="library";render();systemNav()});root.querySelectorAll("[data-open]").forEach(b=>b.onclick=()=>openCondition(b.dataset.open));const add=root.querySelector("#addConditionInline");if(add)add.onclick=()=>newCondition();const templates=root.querySelector("#addTemplates");if(templates)templates.onclick=addStarterChapters;const more=root.querySelector("#addMoreTopics");if(more)more.onclick=addMoreTopics}

const STARTER_CHAPTERS=[
{id:"ankle-sprain",title:"Lateral Ankle Sprain",system:"Musculoskeletal",summary:"Lateral ligament injury, commonly involving the ATFL, after inversion trauma.",definition:"A spectrum of injury to the lateral ankle ligament complex, most often the anterior talofibular ligament.",causes:"Inversion and plantar-flexion mechanism; previous sprain, balance deficits and reduced neuromuscular control increase recurrence risk.",signs:"Lateral pain, swelling, bruising, tenderness, reduced weight-bearing and perceived instability.",assessment:"Use Ottawa Ankle Rules to guide radiography decisions; assess gait, swelling, ROM, strength, balance and functional capacity. Reassess ligament stability when pain permits.",redFlags:"Inability to take four steps or bony tenderness meeting Ottawa criteria warrants imaging assessment; consider fracture, syndesmosis injury, dislocation or neurovascular compromise.",specialTests:"Anterior drawer and talar tilt may help assess ligament laxity after acute irritability settles; squeeze/external-rotation tests if syndesmosis injury suspected.",outcomeMeasures:"Foot and Ankle Ability Measure (FAAM), Cumberland Ankle Instability Tool (CAIT), pain scale, single-leg balance and hop tests.",management:"Early protected weight-bearing as tolerated, compression/elevation for symptoms, progressive ROM, calf/peroneal strength, balance and sport-specific loading.",rehabPlan:"Progress from mobility and isometrics to resisted strengthening, single-leg balance, hopping, agility and return-to-sport criteria.",precautions:"Do not dismiss persistent pain, locking, proximal fibular tenderness or disproportionate swelling; investigate alternative injury.",complications:"Recurrent sprain, chronic ankle instability, osteochondral lesion and persistent symptoms."},
{id:"rotator-cuff",title:"Rotator Cuff Related Shoulder Pain",system:"Musculoskeletal",summary:"Shoulder pain associated with loading of the rotator cuff and related subacromial structures.",definition:"A clinical presentation of shoulder pain and reduced function during elevation or loading; it is not a single definitive tissue diagnosis.",causes:"Load-capacity mismatch, sudden increase in overhead activity, age-related tendon changes and occupational or sporting exposure.",signs:"Pain with reaching or resisted elevation, night pain in some people, painful arc and reduced strength due to pain.",assessment:"History, cervical screen, active and passive ROM, resisted testing, functional tasks and patient goals; interpret clusters of findings rather than one test.",redFlags:"Urgent assessment for suspected fracture, dislocation, infection, malignancy, acute traumatic major weakness or cardiopulmonary referred pain.",differentials:"Cervical radiculopathy, glenohumeral arthritis, adhesive capsulitis, instability and referred visceral pain.",specialTests:"Painful arc, external-rotation resistance and Hawkins-Kennedy may contribute; no single test confirms a specific tendon lesion.",outcomeMeasures:"SPADI, QuickDASH, pain rating, active elevation and patient-specific functional scale.",management:"Education, load modification, progressive rotator cuff and scapular strengthening, graded exposure and sleep/activity advice.",rehabPlan:"Start with tolerable isometrics or low-load isotonic work, then progress resistance, range, speed and overhead function.",precautions:"Avoid prolonged complete rest; adapt loading to irritability and monitor unexpected deterioration.",complications:"Persistent pain, reduced participation, weakness and sleep disruption."},
{id:"adhesive-capsulitis",title:"Adhesive Capsulitis",system:"Musculoskeletal",summary:"Progressive shoulder pain and global restriction of glenohumeral movement, especially external rotation.",definition:"A shoulder condition characterised by painful restriction of active and passive glenohumeral ROM.",causes:"Often idiopathic; associated with diabetes, thyroid disease, immobilisation and previous shoulder pathology.",signs:"Gradual pain, night discomfort and global stiffness with external rotation commonly most restricted.",assessment:"Compare active and passive ROM, capsular pattern, functional reach and symptom irritability; screen neck and alternative causes.",redFlags:"Prompt referral for fever, hot swollen joint, trauma with deformity, unexplained systemic symptoms or suspected malignancy.",outcomeMeasures:"SPADI, QuickDASH, pain scale, goniometric ROM and patient-specific function.",management:"Education about natural history, pain-modulated mobility, graded stretching and strengthening as irritability reduces; medical options are clinician-led.",rehabPlan:"Highly irritable phase: gentle comfortable movement; stiffness-dominant phase: progressive mobility and functional strengthening.",precautions:"Aggressive painful stretching may flare symptoms; tailor intensity to stage and irritability.",complications:"Prolonged disability, sleep disturbance and persistent ROM loss."},
{id:"cervical-radiculopathy",title:"Cervical Radiculopathy",system:"Neurology",summary:"Neck-related nerve-root irritation or dysfunction producing radiating arm symptoms.",definition:"A clinical syndrome of cervical nerve-root dysfunction with arm pain and possible sensory, motor or reflex changes.",causes:"Disc herniation, foraminal narrowing and degenerative changes.",signs:"Neck and arm pain, paraesthesia, dermatomal sensory change, myotomal weakness or altered reflexes.",assessment:"Neurological examination including myotomes, dermatomes and reflexes; cervical ROM and neurodynamic testing; assess function and red flags.",redFlags:"Urgent referral for progressive motor deficit, gait disturbance, hand clumsiness, bilateral symptoms, sphincter change, fever, trauma or suspected myelopathy.",specialTests:"Spurling, upper-limb tension testing, cervical distraction and rotation range may contribute as a test cluster.",outcomeMeasures:"Neck Disability Index, pain rating, neurological findings and patient-specific function.",management:"Education, activity modification, graded exercise and selected manual therapy or neural mobility where appropriate; medical review for severe or progressive deficits.",precautions:"Avoid forceful cervical techniques when myelopathy, instability, vascular pathology or serious pathology is suspected.",complications:"Persistent neuropathic pain, weakness and rarely spinal cord compromise."},
{id:"tkr",title:"Total Knee Arthroplasty Rehabilitation",system:"Musculoskeletal",summary:"Post-operative rehabilitation after total knee replacement to restore mobility, strength and function.",definition:"Rehabilitation following surgical replacement of damaged knee joint surfaces with prosthetic components.",causes:"Usually advanced symptomatic knee osteoarthritis or other severe joint disease after shared decision-making.",signs:"Post-operative pain, swelling, reduced ROM, quadriceps inhibition and altered gait are common early findings.",assessment:"Review surgical precautions and wound status; monitor pain, swelling, ROM, quadriceps activation, transfers, gait and function.",redFlags:"Urgent medical review for suspected DVT/PE, wound drainage or infection, fever, sudden calf swelling, chest pain or acute neurovascular change.",outcomeMeasures:"Knee ROM, Timed Up and Go, 30-second sit-to-stand, gait speed, Oxford Knee Score or KOOS.",management:"Early mobilisation per surgical pathway, swelling management, progressive ROM, quadriceps strengthening, gait and stair training.",rehabPlan:"Progress from transfers and walking aids to progressive resistance, balance, endurance and task-specific community activity.",precautions:"Follow surgeon-specific weight-bearing and wound guidance; avoid unapproved high-impact loading during recovery.",complications:"Infection, thromboembolism, stiffness, persistent pain, instability and prosthesis-related complications."},
{id:"hip-oa",title:"Hip Osteoarthritis",system:"Musculoskeletal",summary:"Degenerative whole-joint hip disorder commonly causing groin pain and reduced mobility.",definition:"A whole-joint condition involving cartilage, bone, synovium and periarticular tissues.",causes:"Age, genetics, previous injury, dysplasia, body mass and altered joint mechanics.",signs:"Groin or anterior thigh pain, stiffness after rest, reduced internal rotation and difficulty walking or dressing.",assessment:"History, gait, hip ROM, strength, functional tasks and red-flag screen; imaging is not always needed for typical presentation.",redFlags:"Rapidly worsening pain, inability to weight-bear, fever, trauma or unexplained systemic symptoms need medical assessment.",outcomeMeasures:"HOOS, WOMAC, pain rating, 30-second sit-to-stand and walking tolerance.",management:"Education, tailored strengthening and aerobic exercise, weight management if appropriate, walking aid advice and shared decisions about medical options.",rehabPlan:"Progress hip and lower-limb strengthening, balance, walking capacity and functional tasks according to symptoms.",precautions:"Adapt exercise to pain response; sudden severe pain or acute loss of function requires reassessment.",complications:"Reduced activity, deconditioning, sleep disruption and participation restriction."},
{id:"osteoporosis",title:"Osteoporosis",system:"Other",summary:"Reduced bone strength and increased fragility-fracture risk.",definition:"A skeletal disorder characterised by compromised bone strength and increased fracture susceptibility.",causes:"Ageing, menopause, low body mass, glucocorticoids, smoking, low activity and secondary endocrine or systemic causes.",signs:"Often asymptomatic until fracture; vertebral fractures may cause height loss, kyphosis and back pain.",assessment:"Fracture history, risk factors, falls, posture, strength and balance; medical assessment may include DXA and fracture-risk tools.",redFlags:"New severe back pain after minor trauma, suspected fragility fracture or sudden height loss warrants prompt assessment.",outcomeMeasures:"Falls history, balance tests, strength, gait speed and functional measures; DXA is medically interpreted.",management:"Progressive resistance and weight-bearing exercise, balance training, falls prevention, adequate nutrition and medical management as indicated.",rehabPlan:"Build strength and balance progressively; include safe impact only when fracture risk and clinical status permit.",precautions:"Avoid loaded end-range spinal flexion or twisting in people at high vertebral-fracture risk; individualise impact and lifting.",complications:"Vertebral, hip and wrist fractures, chronic pain, kyphosis and loss of independence."},
{id:"asthma",title:"Asthma",system:"Cardiorespiratory",summary:"Variable respiratory symptoms and expiratory airflow limitation due to chronic airway inflammation.",definition:"A heterogeneous airway disease characterised by variable respiratory symptoms and variable expiratory airflow limitation.",causes:"Genetic predisposition and environmental triggers including allergens, viral infections, smoke, exercise and occupational exposures.",signs:"Wheeze, breathlessness, chest tightness and cough with variable timing and intensity.",assessment:"Clinical history, trigger pattern, inhaler technique and objective lung-function testing such as spirometry or peak-flow variability.",redFlags:"Severe breathlessness, inability to speak in sentences, cyanosis, exhaustion, altered consciousness or poor response to reliever requires emergency care.",outcomeMeasures:"Asthma Control Test, symptom frequency, reliever use, activity tolerance and spirometry.",management:"Follow an individualised medical action plan, prescribed inhaled therapy, trigger management, education and regular physical activity.",rehabPlan:"Exercise can be beneficial; warm-up, pacing and prescribed pre-exercise medication plan may help those with exercise-induced symptoms.",precautions:"Physiotherapists do not independently alter inhaled medication; recognise acute exacerbation and follow emergency plan.",complications:"Exacerbations, activity limitation, sleep disturbance and rarely life-threatening attacks."},
{id:"bronchiectasis",title:"Bronchiectasis",system:"Cardiorespiratory",summary:"Permanent bronchial dilatation associated with chronic infection, sputum and recurrent exacerbations.",definition:"A chronic respiratory condition involving abnormal permanent dilatation of bronchi and impaired mucus clearance.",causes:"Previous severe infection, immune disorders, cystic fibrosis, ciliary disorders and other underlying diseases.",signs:"Chronic productive cough, sputum, recurrent chest infections, fatigue and breathlessness.",assessment:"Sputum history, exacerbation frequency, exercise capacity, oxygenation and airway-clearance needs; diagnosis uses high-resolution CT.",redFlags:"Significant haemoptysis, severe hypoxaemia, sepsis features or rapidly worsening breathlessness needs urgent medical review.",outcomeMeasures:"St George's Respiratory Questionnaire, Leicester Cough Questionnaire, 6-minute walk test and exacerbation frequency.",management:"Individualised airway-clearance techniques, exercise training, hydration advice and multidisciplinary respiratory care.",rehabPlan:"Teach and review airway clearance; combine with aerobic and resistance training adjusted to symptoms and exacerbation status.",precautions:"Technique selection should be individualised; infection-control precautions and sputum changes matter.",complications:"Recurrent infection, haemoptysis, respiratory failure and reduced exercise capacity."},
{id:"sci",title:"Spinal Cord Injury",system:"Neurology",summary:"Damage to the spinal cord causing motor, sensory and autonomic impairment below the lesion.",definition:"Traumatic or non-traumatic spinal cord damage resulting in temporary or permanent neurological dysfunction.",causes:"Trauma, vascular events, tumour, infection and inflammatory disease.",signs:"Weakness or paralysis, sensory change, altered reflexes, autonomic dysfunction and possible respiratory impairment depending on level.",assessment:"Use neurological classification such as ISNCSCI/ASIA by trained clinicians; assess respiratory function, skin, ROM, strength, transfers and function.",redFlags:"Autonomic dysreflexia symptoms (sudden hypertension, headache, flushing/sweating), respiratory compromise or new neurological loss require urgent response.",outcomeMeasures:"SCIM, WISCI II, functional mobility, respiratory measures and skin integrity monitoring.",management:"Multidisciplinary rehabilitation: positioning, respiratory care, ROM, strengthening of available muscles, transfers, wheelchair skills and self-management.",rehabPlan:"Set goals by neurological level and completeness; progressively train bed mobility, transfers, wheelchair or gait where appropriate.",precautions:"Prevent pressure injury, contracture, falls and autonomic dysreflexia; respect bone health and orthostatic tolerance.",complications:"Pressure injuries, urinary and bowel dysfunction, spasticity, pain, DVT and autonomic dysreflexia."},
{id:"cerebral-palsy",title:"Cerebral Palsy",system:"Paediatrics",summary:"A group of permanent disorders of movement and posture due to a non-progressive disturbance in the developing brain.",definition:"A group of permanent disorders of movement and posture causing activity limitation, attributed to non-progressive disturbances in the developing fetal or infant brain.",causes:"Prenatal, perinatal or early postnatal brain injury or altered development; often no single cause is identified.",signs:"Variable tone, movement and postural control, delayed motor milestones, contracture risk and possible associated communication, vision or epilepsy needs.",assessment:"Family-centred history, developmental and functional assessment, GMFCS level, range, strength, participation and equipment needs.",redFlags:"Loss of previously acquired skills or new neurological signs are not typical and need medical evaluation.",outcomeMeasures:"GMFM-66/88, PEDI-CAT, goal attainment and participation measures.",management:"Goal-directed task practice, strengthening, mobility and balance training, play-based activity, orthoses or equipment via team-based decisions.",rehabPlan:"Set family-prioritised goals and practise meaningful tasks across home, school and community contexts.",precautions:"Monitor hip displacement, pain, growth-related contracture and fatigue; coordinate with paediatric team.",complications:"Hip displacement, contractures, pain, fatigue, reduced participation and secondary musculoskeletal problems."},
{id:"vestibular-hypofunction",title:"Peripheral Vestibular Hypofunction",system:"Neurology",summary:"Reduced vestibular function causing gaze instability, dizziness and balance difficulty.",definition:"Partial or complete reduction in vestibular end-organ or nerve function, unilateral or bilateral.",causes:"Vestibular neuritis, ototoxicity, surgery, infection and other inner-ear disorders.",signs:"Oscillopsia, dizziness with head movement, imbalance, motion sensitivity and difficulty in darkness or on uneven ground.",assessment:"History and neurological/oculomotor screen; assess gait, balance, dynamic visual acuity and vestibular function within training and referral scope.",redFlags:"New severe continuous vertigo with focal neurological signs, severe headache, inability to stand, chest pain or acute hearing loss needs urgent medical evaluation.",outcomeMeasures:"Dizziness Handicap Inventory, Activities-specific Balance Confidence scale, Dynamic Gait Index and dynamic visual acuity.",management:"Individualised gaze-stabilisation, balance and habituation exercises after appropriate diagnosis and screening.",rehabPlan:"Progress gaze-stability speed/duration, stance and gait challenges, sensory conditions and functional head movements.",precautions:"Stop and refer for atypical neurological symptoms; avoid unsupervised high-risk balance tasks in fall-prone individuals.",complications:"Falls, activity avoidance, visual blurring and reduced confidence."}
];

const MORE_TOPICS=[
["plantar-fasciitis","Plantar Heel Pain / Plantar Fasciopathy","Musculoskeletal","Load-related plantar heel pain, often most noticeable with first steps after rest.","A clinical presentation of plantar-medial heel pain commonly associated with the plantar fascia.","Running or walking load changes, prolonged standing, calf capacity, foot mechanics and other individual factors.","Medial plantar heel tenderness, start-up pain and pain with prolonged loading.","History, gait, ankle dorsiflexion, calf strength, foot function and differential screen.","Consider calcaneal stress fracture, infection, inflammatory disease, nerve entrapment or unexplained night pain.","Load modification, progressive calf and foot strengthening, education and graded return to activity.","Progress from tolerable isometrics and calf raises to heavy slow resistance, hopping and running exposure as appropriate.","Avoid assuming all heel pain is plantar fascia pathology; reassess atypical or worsening symptoms.","Foot Function Index, FAAM, pain scale, single-leg heel raises.","Windlass test may support the clinical picture but is not diagnostic alone.","Calcaneal stress injury, fat-pad pain, tarsal tunnel syndrome, referred lumbar pain.","Persistent pain, reduced walking and activity limitation."],
["achilles-tendinopathy","Achilles Tendinopathy","Musculoskeletal","Load-related pain and impaired function in the Achilles tendon.","A clinical tendon disorder characterised by load-related pain, swelling or thickening and reduced tendon function.","Sudden running or jumping load increase, inadequate recovery, reduced calf capacity and age-related tendon changes.","Local tendon pain, morning stiffness, tenderness and reduced heel-raise or hopping capacity.","Map pain location, palpate tendon, assess calf strength/endurance, ankle function and training load.","Sudden snap, palpable gap, marked loss of push-off or positive rupture suspicion requires urgent assessment.","Progressive tendon loading, education, temporary load adjustment and graded return to running; consider insertional versus midportion presentation.","Begin with tolerable calf loading, progress resistance and repetitions, then energy-storage tasks, hops and running.","Avoid aggressive compression or dorsiflexion loading in irritable insertional symptoms; screen for rupture.","VISA-A, heel-rise work test, pain rating and running tolerance.","Single-leg heel raise and hop loading; Thompson test when rupture is suspected.","Retrocalcaneal bursitis, partial/complete rupture, referred pain.","Persistent tendon pain, reduced sport participation and rupture."],
["meniscal-injury","Knee Meniscal Injury","Musculoskeletal","Knee pain after twisting or degenerative change, sometimes with effusion and mechanical symptoms.","Injury or degeneration of the medial or lateral meniscal fibrocartilage.","Loaded rotation, deep flexion, sport trauma or age-related degeneration.","Joint-line pain, swelling, catching, limited flexion and pain with pivoting or squatting.","Mechanism, effusion, ROM, joint line, ligament screen and function; imaging decisions depend on context.","Locked knee, inability to extend, fracture concern, large acute effusion or neurovascular signs need prompt assessment.","Education, progressive quadriceps/hip strengthening and functional rehabilitation; surgical opinion for selected locked or persistent cases.","Restore extension and flexion, strength, single-leg control, then running and pivoting if required.","Do not equate clicking with a surgically important tear; follow post-operative restrictions if applicable.","KOOS, IKDC, Lysholm, effusion, ROM and functional hop tests.","Joint-line tenderness, McMurray and Thessaly may contribute but have limitations.","ACL injury, osteoarthritis flare, patellofemoral pain, loose body.","Persistent pain, recurrent effusion, mechanical block and reduced function."],
["patellofemoral-pain","Patellofemoral Pain","Musculoskeletal","Pain around or behind the patella during loaded knee flexion tasks.","A common musculoskeletal presentation involving peripatellar or retropatellar pain during activities loading the patellofemoral joint.","Training-load change, running, stairs, squatting, prolonged sitting and individual strength or movement factors.","Pain with stairs, squats, running or prolonged sitting; usually no large effusion.","History, functional squat/step tasks, hip and knee strength, load history and differential screen.","Large effusion, true locking, acute trauma, fever or inability to weight-bear warrants reassessment.","Education, load adjustment and progressive knee-targeted with or without hip-targeted strengthening.","Progress from tolerable quadriceps/hip work to single-leg tasks, stairs, running and sport-specific loading.","Avoid relying on patellar position or one special test as a definitive cause.","Anterior Knee Pain Scale (Kujala), KOOS-PF, pain and functional tasks.","Squat, step-down and patellar loading may reproduce familiar pain; no single test confirms diagnosis.","Patellar tendinopathy, meniscal pathology, osteoarthritis, referred hip pain.","Persistent pain, reduced sport and activity participation."],
["lumbar-spinal-stenosis","Lumbar Spinal Stenosis","Musculoskeletal","Neurogenic claudication or radicular symptoms associated with narrowing of lumbar spinal canal or foramina.","A clinical syndrome where degenerative narrowing may compromise neural structures, often producing posture-dependent leg symptoms.","Age-related facet, ligament and disc changes; spondylolisthesis may contribute.","Leg pain, heaviness, paraesthesia or weakness with standing/walking, often eased by sitting or flexion.","Neurological screen, walking tolerance, posture response, vascular differential and function.","New saddle sensory loss, bladder/bowel dysfunction, progressive weakness or bilateral neurological changes require emergency assessment.","Education, graded walking or cycling, strength and balance training; coordinate medical review for progressive deficits.","Use symptom-tolerated aerobic conditioning, trunk/hip strengthening and functional walking progression.","Do not assume all exertional leg pain is spinal; assess vascular claudication and red flags.","Zurich Claudication Questionnaire, ODI, walking distance and pain scale.","Repeated movement and neurodynamic tests may assist differential reasoning; imaging correlates imperfectly with symptoms.","Peripheral arterial disease, hip OA, peripheral neuropathy, disc radiculopathy.","Reduced walking capacity, falls and persistent neurological symptoms."],
["lumbar-disc-herniation","Lumbar Disc Herniation with Radicular Pain","Musculoskeletal","Back and leg pain associated with nerve-root irritation, often with neurological symptoms.","Displacement of disc material may be associated with nerve-root inflammation or compression and radicular symptoms.","Disc degeneration, lifting or bending exposure, age and individual susceptibility.","Leg-dominant radiating pain, paraesthesia, sensory or motor change; cough/sneeze may aggravate.","Neurological examination, myotomes, dermatomes, reflexes, gait, symptom distribution and function.","Cauda equina symptoms, progressive motor loss, saddle anaesthesia or new bladder/bowel dysfunction are emergencies.","Education, remain active as tolerated, graded exercise and symptom-guided rehabilitation; medical referral for severe/progressive deficits.","Progress from tolerable movement and walking to trunk/hip strength and meaningful activity; individualise directional preference if present.","Avoid aggressive techniques with progressive neurological deficit or serious pathology suspicion.","Oswestry Disability Index, Roland-Morris, pain and neurological findings.","Straight-leg raise and crossed straight-leg raise can support assessment in context.","Hip pathology, peripheral neuropathy, spinal stenosis, non-specific referred pain.","Persistent radicular pain, weakness and activity limitation."],
["hip-fracture","Hip Fracture Rehabilitation","Geriatrics","Rehabilitation after proximal femoral fracture, with focus on mobility, strength and safe participation.","A fracture of the proximal femur, commonly following a fall or fragility event in older adults.","Falls, osteoporosis, frailty, reduced balance and high-energy trauma.","Hip/groin pain, inability to weight-bear, shortened or externally rotated limb in some displaced fractures.","Review surgical procedure, weight-bearing orders, pain, cognition, orthostatic response, transfers and gait.","Suspected fracture after fall, sudden deterioration, wound infection, DVT/PE or neurovascular compromise requires urgent care.","Early mobilisation according to surgical orders, progressive strength, balance, gait and falls prevention.","Progress bed mobility and transfers to walking aids, stairs, endurance and home/community goals.","Follow fixation/replacement-specific precautions and monitor delirium, orthostasis and falls risk.","Timed Up and Go, gait speed, 30-second sit-to-stand, Barthel Index and mobility level.","Functional mobility assessment rather than provocative special tests in acute fracture care.","Periprosthetic fracture, DVT, delirium, deconditioning and other fragility fractures.","Loss of independence, falls, reduced mobility and mortality risk."],
["parkinsons-disease","Parkinson's Disease","Neurology","Progressive neurological condition affecting movement, balance and non-motor function.","A neurodegenerative disorder associated with dopaminergic neuronal loss and motor and non-motor symptoms.","Usually multifactorial; age and genetic/environmental factors contribute.","Bradykinesia, rigidity, tremor, reduced arm swing, freezing, postural instability and non-motor symptoms.","Observe gait, turning, transfers, balance, dual-task function, falls, medication timing and patient goals.","Sudden new focal deficits, acute confusion, fever/rigidity or rapid deterioration need medical assessment.","Task-specific exercise, cueing, gait and balance training, strength, aerobic activity and falls education.","Practise amplitude-based movement, turning, obstacle negotiation, dual-tasking and functional strategies.","Adapt sessions to medication fluctuations, fatigue, cognition, orthostatic hypotension and fall risk.","Mini-BESTest, Berg Balance Scale, 10-m walk, TUG, 6-minute walk and PDQ-39.","Timed gait, turning, freezing observation and functional mobility measures.","Stroke, atypical parkinsonism, medication effects, vestibular and musculoskeletal causes of falls.","Falls, freezing-related injury, reduced independence and deconditioning."],
["multiple-sclerosis","Multiple Sclerosis","Neurology","Immune-mediated central nervous system disease with variable neurological symptoms and fatigue.","A chronic inflammatory demyelinating disease of the central nervous system with heterogeneous course.","Immune, genetic and environmental factors; individual disease course varies.","Fatigue, weakness, sensory change, visual symptoms, spasticity, ataxia and balance impairment.","Neurological history, fatigue, strength, tone, balance, gait, vision, heat sensitivity and participation.","Acute severe visual loss, new major neurological deficit, infection or sudden atypical symptoms require medical review.","Individualised aerobic/resistance exercise, mobility, balance, energy conservation and multidisciplinary support.","Use interval training and pacing; progress strength and gait while monitoring recovery and fatigue.","Avoid overheating and overwork; adapt exercise during relapse or infection with clinical team guidance.","MS Walking Scale-12, 6-minute walk, fatigue scales, MSIS-29 and balance measures.","Functional neurological assessment; no single bedside test diagnoses MS.","Stroke, spinal cord compression, peripheral neuropathy and other causes of neurological symptoms.","Fatigue, falls, reduced participation and progressive disability in some people."],
["guillain-barre","Guillain-Barré Syndrome","Neurology","Acute immune-mediated peripheral neuropathy causing rapidly evolving weakness.","A group of acute immune-mediated polyradiculoneuropathies, often following infection.","Post-infectious immune response; specific triggers vary.","Ascending weakness, reduced reflexes, sensory symptoms, pain and possible cranial, respiratory or autonomic involvement.","Monitor strength, respiratory function, cough, swallowing, autonomic signs and functional change with specialist team.","Rapid progression, breathlessness, weak cough, swallowing difficulty or autonomic instability is an emergency.","Acute phase requires medical/neurocritical care; rehabilitation focuses on safe positioning, ROM and gradual functional recovery.","Avoid overwork; graded strengthening and mobility only as medically stable, with planned rest and monitoring.","Monitor respiratory decline, fatigue, pain, orthostatic and autonomic instability; coordinate closely with specialist team.","MRC sum score, GBS disability scale, FIM/SCIM as appropriate, respiratory measures and fatigue.","Serial neurological and respiratory monitoring rather than provocative orthopaedic tests.","Spinal cord compression, myasthenia, myopathy and other acute neuropathies.","Respiratory failure, autonomic complications, pain and prolonged weakness."],
["stroke-rehab","Stroke Rehabilitation","Neurology","Rehabilitation addressing motor, sensory, cognitive and participation changes after stroke.","A cerebrovascular event causing focal neurological injury due to ischaemia or haemorrhage.","Hypertension, atrial fibrillation, diabetes, smoking and vascular risk factors.","Unilateral weakness, altered sensation, facial weakness, speech/vision changes, neglect and balance impairment.","Review stroke type and medical stability; assess motor control, sensation, cognition, neglect, swallowing status, transfers and goals.","New FAST symptoms or sudden neurological change is an emergency; follow local stroke pathway immediately.","Task-specific repetitive practice, strength, aerobic conditioning, balance, gait, upper-limb practice and caregiver education.","Set meaningful goals; progress transfers, sit-to-stand, walking, reaching and community participation.","Monitor fatigue, shoulder pain, falls, tone, cognition and cardiovascular tolerance.","Fugl-Meyer, 10-m walk, 6-minute walk, Berg, ARAT, Barthel Index and Stroke Impact Scale.","Tone, motor control, sensory and functional movement assessment; no single special test diagnoses stroke.","TIA, seizure, hypoglycaemia, migraine and other acute neurological conditions.","Falls, contracture, shoulder pain, spasticity, depression and recurrent stroke."],
["copd","Chronic Obstructive Pulmonary Disease (COPD)","Cardiorespiratory","Chronic respiratory disease with persistent airflow limitation and symptom burden.","A heterogeneous lung condition characterised by chronic respiratory symptoms and airflow obstruction, commonly due to airway/alveolar abnormalities.","Tobacco smoke, biomass exposure, occupational dust/fumes and genetic factors such as alpha-1 antitrypsin deficiency.","Breathlessness, cough, sputum, wheeze, reduced exercise tolerance and exacerbations.","Spirometry interpreted by clinician, symptom burden, exacerbations, oxygenation, exercise capacity, nutrition and inhaler technique.","Severe breathlessness, cyanosis, confusion, chest pain or acute respiratory distress requires urgent care.","Pulmonary rehabilitation, education, breathing strategies, airway clearance when indicated and prescribed inhaler optimisation by medical team.","Individualised interval/continuous aerobic and resistance training with pacing and symptom monitoring.","Oxygen use and targets require prescription; monitor desaturation and exacerbation signs.","CAT, mMRC, 6-minute walk, sit-to-stand, BODE components and quality-of-life measures.","Breathing pattern, exercise response and sputum assessment; spirometry is diagnostic and medically interpreted.","Heart failure, asthma, bronchiectasis, anaemia and deconditioning.","Exacerbations, respiratory failure, frailty and reduced participation."],
["heart-failure","Heart Failure Rehabilitation","Cardiorespiratory","Exercise and self-management support for people living with heart failure.","A clinical syndrome caused by structural or functional cardiac abnormality leading to raised filling pressures or inadequate output.","Ischaemic heart disease, hypertension, cardiomyopathy, valvular disease and arrhythmias.","Breathlessness, fatigue, oedema, orthopnoea and reduced exercise tolerance.","Review clinical stability, symptoms, weight trends, vitals, medication and exercise response; use team-approved risk stratification.","Acute chest pain, syncope, severe breathlessness at rest, rapid fluid gain or decompensation signs require urgent medical review.","Medically supervised cardiac rehabilitation, education, pacing, resistance and aerobic exercise when stable.","Begin at an individually prescribed intensity; progress duration before intensity and monitor recovery.","Do not exercise during acute decompensation or unstable symptoms; follow cardiac team parameters.","6-minute walk, peak VO2 where available, KCCQ, NYHA class and sit-to-stand.","Vitals and exertional symptom monitoring; no orthopaedic special test diagnoses heart failure.","COPD, anaemia, ischaemia, arrhythmia and deconditioning.","Hospitalisation, arrhythmia, falls and reduced quality of life."],
["pneumonia","Pneumonia and Respiratory Physiotherapy","Cardiorespiratory","Acute infection of lung tissue that may impair gas exchange and exercise capacity.","Infection causing inflammation and consolidation of lung parenchyma.","Bacterial, viral or aspiration-related pathogens; risk increases with age and comorbidity.","Cough, fever, sputum, pleuritic pain, breathlessness, fatigue and hypoxaemia.","Review imaging and medical plan, oxygenation, respiratory rate, sputum, mobility and functional reserve.","Severe hypoxaemia, sepsis, confusion, hypotension or respiratory distress requires urgent escalation.","Early mobilisation, positioning, breathing support and airway clearance only when clinically indicated; medical treatment is primary.","Progress bed mobility, sitting, standing and walking as stable; build endurance during recovery.","Routine airway-clearance techniques are not indicated for every pneumonia case; follow infection-control precautions.","Oxygen saturation, respiratory rate, 6-minute walk or sit-to-stand, functional mobility and symptom scores.","Auscultation and sputum assessment may inform care but do not independently diagnose pneumonia.","Pulmonary oedema, PE, COPD exacerbation, heart failure and atelectasis.","Respiratory failure, sepsis, deconditioning and prolonged fatigue."],
["cystic-fibrosis","Cystic Fibrosis","Cardiorespiratory","Inherited multisystem condition with thick secretions and chronic respiratory disease.","Autosomal recessive CFTR-related disorder affecting epithelial ion transport and mucus properties.","Pathogenic variants in CFTR gene.","Chronic productive cough, recurrent infection, bronchiectasis, malabsorption and variable exercise limitation.","Multidisciplinary review, lung function, sputum microbiology, nutrition, exercise capacity and airway-clearance needs.","Significant haemoptysis, severe breathlessness, acute hypoxaemia or rapid deterioration requires urgent specialist review.","Individualised airway clearance, exercise, nutrition and prescribed CFTR-modulator/medical care by specialist team.","Combine airway-clearance routine with aerobic and resistance activity, adapting for exacerbations and age.","Strict infection-control precautions between people with CF; airway-clearance plan is individualised.","FEV1, 6-minute walk, CFQ-R, exercise capacity and exacerbation frequency.","Sputum and respiratory assessment; tests interpreted within specialist CF service.","Asthma, primary ciliary dyskinesia, immunodeficiency and other bronchiectasis causes.","Progressive lung disease, infection, malnutrition and diabetes-related complications."],
["lymphoedema","Lymphoedema","Women's Health","Chronic tissue swelling due to impaired lymphatic transport, often affecting a limb.","Accumulation of protein-rich interstitial fluid due to lymphatic system dysfunction.","Primary lymphatic abnormality or secondary damage after cancer treatment, surgery, radiotherapy, infection or trauma.","Persistent swelling, heaviness, tightness, skin changes and reduced limb function.","History, limb volume/circumference, skin assessment, symptoms, function and differential including venous disease or DVT.","Sudden painful swelling, redness/heat, fever, suspected DVT or acute breathlessness requires urgent medical assessment.","Specialist-led decongestive care may include compression, exercise, skin care and manual techniques as appropriate.","Progressive muscle-pump exercise, mobility and self-management with prescribed compression when indicated.","Compression requires individual assessment; monitor skin, sensation, arterial status and infection.","Limb volume, LYMQOL, Lymph-ICF and functional goals.","Circumference/volume measurement and Stemmer sign can support assessment but are not definitive alone.","DVT, venous insufficiency, infection, cardiac or renal oedema.","Cellulitis, fibrosis, skin changes and functional restriction."],
["pelvic-floor-dysfunction","Pelvic Floor Dysfunction","Women's Health","Symptoms associated with impaired pelvic floor muscle coordination, strength or relaxation.","A broad group of conditions involving pelvic floor muscle overactivity, underactivity or coordination problems.","Pregnancy, childbirth, surgery, ageing, chronic straining, pain and other individual factors.","Urinary or faecal leakage, urgency, pelvic pain, prolapse symptoms or difficulty relaxing.","Sensitive consent-based history, bladder/bowel diary, functional impact and pelvic health assessment by trained practitioner.","Unexplained bleeding, acute retention, new saddle anaesthesia, severe pain, fever or suspected malignancy requires medical review.","Individualised pelvic health physiotherapy, education, bladder/bowel strategies and muscle training only when indicated.","Train contraction, relaxation, coordination and functional strategies according to assessment findings.","Internal examination only with specific training, consent and local scope; avoid strengthening an overactive painful pelvic floor without assessment.","ICIQ-UI SF, PFDI-20, PFIQ-7, bladder diary and patient goals.","Pelvic floor muscle assessment by appropriately trained clinician; no one-size-fits-all exercise prescription.","UTI, prolapse, endometriosis, bladder pain syndrome and neurological causes.","Persistent leakage, pain, sexual and participation impacts."],
["pregnancy-msk","Pregnancy-Related Musculoskeletal Pain","Women's Health","Musculoskeletal pain during pregnancy, often involving pelvic girdle or lumbar regions.","A clinical presentation of pregnancy-associated pain influenced by mechanical, hormonal and psychosocial factors.","Pregnancy-related load changes, previous pelvic pain, activity demands and individual factors.","Pelvic girdle, lumbar or hip pain; difficulty with walking, stairs, turning in bed or single-leg tasks.","History, pain location, function, gait and appropriate pelvic girdle tests; screen obstetric symptoms and red flags.","Vaginal bleeding, fluid loss, contractions, severe headache, calf swelling/pain, chest pain or reduced fetal movement requires obstetric advice urgently.","Education, pacing, comfortable movement, tailored strengthening, support strategies and obstetric team coordination.","Maintain safe activity, graded hip/trunk strength and functional movement modifications based on symptoms.","Exercise and manual therapy must be adapted to pregnancy stage, comorbidities and obstetric guidance.","Pelvic Girdle Questionnaire, pain scale, Patient-Specific Functional Scale and walking tolerance.","P4/thigh thrust, FABER and other pelvic girdle tests used as a cluster by trained clinicians.","Hip pathology, lumbar radiculopathy, urinary/obstetric causes and inflammatory conditions.","Persistent pain, reduced mobility, sleep and participation limitation."],
["diastasis-recti","Diastasis Recti Abdominis","Women's Health","Widening and thinning of the linea alba with separation between rectus abdominis muscle bellies.","A change in inter-rectus distance and linea alba function, commonly occurring during and after pregnancy.","Pregnancy-related abdominal wall stretching, multiple pregnancy and individual connective-tissue factors.","Abdominal midline doming, perceived core weakness or functional concerns; may be asymptomatic.","Assess symptoms, abdominal wall tension/function, breathing, load transfer and relevant pelvic floor symptoms; distance alone is not the whole picture.","Severe abdominal pain, suspected hernia, acute mass or systemic symptoms needs medical assessment.","Education and graded abdominal wall rehabilitation integrated with functional tasks; address associated pelvic floor issues.","Progress breathing and low-load control to lifting, transfers, resistance and sport-specific tasks as tolerated.","Avoid blanket exercise bans; adjust load if symptomatic doming or pain and assess for hernia when suspected.","Inter-rectus distance alongside functional measures, pain and patient-specific goals.","Palpation or ultrasound measurement may quantify separation; function and symptoms guide care.","Umbilical/ventral hernia, pelvic floor dysfunction and abdominal pain causes.","Body image distress, discomfort and functional limitation in some people."],
["developmental-coordination","Developmental Coordination Disorder","Paediatrics","Motor coordination difficulties that interfere with daily activities, school and play.","A neurodevelopmental disorder involving motor skill acquisition and execution below age expectations with functional impact.","Neurodevelopmental factors; often co-occurs with ADHD, learning or sensory differences.","Clumsiness, slow motor learning, difficulty with handwriting, dressing, sports or playground skills.","Developmental history, participation-based assessment, motor coordination testing and school/family priorities.","Regression, focal neurological signs, new weakness or loss of skills requires medical evaluation.","Task-oriented, goal-directed practice, environmental adaptations and family/school collaboration.","Practise meaningful real-life tasks with repetition, feedback and graded challenge.","Avoid framing the child as unmotivated; consider attention, confidence, sensory needs and fatigue.","MABC-2, BOT-2, DCDQ and goal attainment.","Standardised motor coordination assessment by trained clinicians.","Cerebral palsy, muscular dystrophy, visual impairment and other neurodevelopmental conditions.","Reduced participation, confidence and physical activity."],
["developmental-dysplasia-hip","Developmental Dysplasia of the Hip","Paediatrics","Abnormal development or stability of the hip joint in infancy and childhood.","A spectrum from acetabular dysplasia to subluxation or dislocation of the femoral head.","Breech presentation, family history, female sex and positional factors.","Often asymptomatic; limited abduction, leg-length difference or asymmetric folds may be observed.","Newborn/infant screening and imaging decisions by paediatric clinicians; physiotherapists monitor movement and treatment function.","Painful limp in older child, delayed walking or suspected dislocation warrants prompt paediatric assessment.","Management is age- and severity-dependent, often involving harnessing or orthopaedic care; support family education and prescribed mobility.","Follow orthopaedic plan; support age-appropriate motor development and monitor ROM/function.","Do not force hip positioning or independently alter harness/brace settings; follow paediatric orthopaedic guidance.","Age-appropriate hip ROM, motor milestones and imaging measures interpreted by specialist.","Barlow/Ortolani are specialist newborn screening manoeuvres, not general physiotherapy tests.","Transient synovitis, septic arthritis, neuromuscular hip displacement and other causes of limp.","Residual dysplasia, gait changes and early hip osteoarthritis."],
["vestibular-bppv","Benign Paroxysmal Positional Vertigo (BPPV)","Neurology","Brief position-triggered vertigo caused by displaced otoconia within semicircular canals.","A peripheral vestibular disorder where otoconia enter a semicircular canal and cause positional vertigo.","Often idiopathic; age, head trauma and inner-ear conditions may contribute.","Brief spinning with rolling in bed, looking up or bending; positional nystagmus may be present.","History, neurological screen and canal-specific positional testing by trained clinician; identify atypical features.","New focal neurological signs, severe headache, inability to stand, acute hearing loss or continuous severe vertigo requires urgent assessment.","Canalith repositioning manoeuvre selected for affected canal and side; education and reassessment.","Reassess symptoms and positional findings; vestibular exercises may be added for residual imbalance.","Use caution with cervical/vascular limitations and falls risk; manoeuvres require appropriate training.","Dizziness Handicap Inventory, symptom resolution and balance/gait measures.","Dix-Hallpike and supine roll tests interpreted by canal-specific nystagmus pattern.","Vestibular migraine, central positional vertigo, orthostatic hypotension and stroke.","Falls, motion avoidance and persistent dizziness."],
["peripheral-neuropathy","Peripheral Neuropathy","Neurology","Peripheral nerve dysfunction causing sensory, motor or autonomic symptoms.","A broad disorder affecting peripheral nerves with varied causes and patterns.","Diabetes, alcohol, nutritional deficiency, medications, autoimmune disease, compression and inherited conditions.","Distal numbness, burning pain, reduced sensation, weakness, altered reflexes and balance problems.","Neurological screen, sensory testing, strength, reflexes, gait, footwear/skin and falls risk; medical work-up for cause.","Rapidly progressive weakness, acute foot drop, autonomic instability or new bowel/bladder/saddle symptoms needs urgent assessment.","Cause-directed medical care, balance and strength training, gait aids, foot protection and education.","Progress functional strengthening, balance and gait practice with sensory compensation strategies.","Protect insensate skin, inspect feet, monitor falls and avoid excessive heat or pressure.","Monofilament, vibration, MRC strength, gait speed, TUG and neuropathy-specific scales.","Sensory mapping, reflexes and nerve tension where relevant; electrodiagnostics are medical tests.","Radiculopathy, spinal stenosis, myelopathy, vascular disease and central causes.","Falls, foot ulceration, pain and reduced independence."],
["ankylosing-spondylitis","Axial Spondyloarthritis / Ankylosing Spondylitis","Musculoskeletal","Inflammatory spinal condition causing chronic back pain and stiffness, often improving with movement.","A chronic inflammatory rheumatic disease affecting axial joints and entheses; radiographic ankylosing spondylitis is one subtype.","Genetic association including HLA-B27 and immune-mediated inflammation.","Inflammatory back pain, morning stiffness, reduced spinal mobility, fatigue and possible extra-articular symptoms.","History of onset and inflammatory pattern, spinal mobility, chest expansion, function and systemic review; diagnosis is rheumatology-led.","Acute painful red photophobic eye may indicate uveitis and needs same-day eye assessment; chest pain, fracture after trauma or neurological deficit needs urgent care.","Regular exercise, posture and mobility work, strengthening, aerobic activity and coordination with rheumatology.","Maintain spinal and hip mobility, extension capacity, breathing/chest expansion and general conditioning.","Avoid high-velocity spinal manipulation in advanced ankylosis or osteoporosis; adapt for active inflammation and fracture risk.","BASDAI, BASFI, spinal mobility measures and chest expansion.","Modified Schober, occiput-to-wall and chest expansion are monitoring measures, not diagnostic alone.","Mechanical back pain, infection, malignancy and other inflammatory arthropathies.","Reduced spinal mobility, osteoporosis, uveitis and cardiovascular comorbidity."],
["fibromyalgia","Fibromyalgia","Other","Chronic widespread pain condition with fatigue, sleep and cognitive symptoms.","A chronic pain syndrome involving altered pain processing and multisystem symptoms.","Multifactorial biopsychosocial influences; often associated with sleep disturbance and stressors.","Widespread pain, fatigue, non-restorative sleep, cognitive symptoms and sensory sensitivity.","History, symptom distribution and impact; screen for alternative or coexisting conditions without excessive testing.","New focal neurological deficit, fever, unexplained weight loss or inflammatory joint signs require assessment for other pathology.","Education, pacing, sleep support, graded exercise and multidisciplinary pain management.","Start with tolerable low-dose aerobic and resistance exercise; progress gradually with recovery and patient preference.","Avoid boom-bust cycles and overly aggressive exercise progression; validate symptoms and adapt to flare patterns.","FIQR, pain rating, fatigue scale, sleep quality and functional goals.","No confirmatory special test; use accepted diagnostic criteria and clinical assessment.","Inflammatory rheumatic disease, hypothyroidism, sleep disorders and neuropathic pain.","Persistent pain, fatigue, reduced participation and mood/sleep effects."],
["rotator-cuff-tear","Rotator Cuff Tear","Musculoskeletal","Partial or full-thickness tendon disruption causing shoulder pain and weakness.","Structural defect in one or more rotator cuff tendons, which may be traumatic or degenerative.","Acute trauma, age-related tendon degeneration and repetitive loading.","Shoulder pain, weakness, reduced active elevation and night pain; traumatic tears may cause sudden functional loss.","History, active/passive ROM, resisted strength, lag signs and functional impact; imaging and specialist opinion as indicated.","Acute traumatic inability to elevate arm, suspected fracture/dislocation or neurovascular injury needs prompt assessment.","Non-operative progressive exercise and education for many presentations; surgical referral considered for selected acute traumatic tears or persistent disability.","Restore comfortable ROM, scapular control and progressive cuff/deltoid strength; build overhead function.","Avoid assuming imaging abnormality explains symptoms; monitor major weakness and response to rehabilitation.","SPADI, QuickDASH, strength, ROM and patient-specific function.","External rotation lag, drop-arm and resisted tests may contribute; diagnostic accuracy varies.","Cervical radiculopathy, adhesive capsulitis, glenohumeral OA and referred pain.","Persistent weakness, pain and functional limitation."],
["acl-rehabilitation","ACL Injury Rehabilitation","Sports & Exercise","Criteria-based rehabilitation after ACL injury or reconstruction.","A structured programme to restore knee function, strength, neuromuscular control and confidence after ACL injury.","ACL rupture, associated meniscal/cartilage injury and individual sport demands.","Effusion, extension loss, quadriceps weakness, instability and reduced hop/run capacity.","Assess swelling, ROM, strength symmetry, movement quality, hop capacity, psychological readiness and surgical restrictions.","New calf swelling/pain, chest pain, wound infection, locked knee or acute re-injury needs urgent review.","Progressive strength, neuromuscular training, running, plyometrics and sport-specific drills with shared decisions.","Use criteria as well as time: quiet knee, full ROM, strength and hop performance, movement quality and psychological readiness before return to sport.","No single time point guarantees safety; follow surgeon/physio protocol and avoid premature pivoting sport.","IKDC, ACL-RSI, quadriceps strength symmetry, hop battery and patient goals.","Lachman/pivot shift for diagnosis; functional hop and movement tests for progression.","Meniscal injury, patellofemoral pain, graft complications and contralateral injury.","Re-injury, persistent weakness, reduced confidence and post-traumatic OA."],
["falls-prevention","Falls Risk Assessment and Prevention","Geriatrics","Multifactorial assessment and intervention to reduce falls and injury in older adults.","A structured approach to identify modifiable intrinsic and environmental fall risks.","Previous falls, impaired balance/strength, medications, vision, orthostatic hypotension, hazards and frailty.","Unsteadiness, fear of falling, gait change, recurrent falls or difficulty with transfers.","Ask about falls circumstances, gait, balance, strength, medications, vision, footwear, cognition and home environment.","Syncope, head injury, anticoagulant use after head strike, acute neurological change or serious injury needs urgent assessment.","Progressive balance and strength exercise, medication/vision review via clinicians, home hazard modification and education.","Challenge balance safely with functional stepping, sit-to-stand, gait and reactive tasks; individualise supervision.","Use appropriate guarding and aids; address orthostatic symptoms and footwear; do not rely on one screening score alone.","Timed Up and Go, 30-second chair stand, gait speed, Berg or Mini-BESTest and falls diary.","Functional balance and gait tests; assess orthostatic blood pressure when indicated.","Syncope, vestibular disorders, neuropathy, medication effects and acute illness.","Fracture, fear-related activity restriction, loss of independence."],
["sarcopenia","Sarcopenia","Geriatrics","Progressive loss of muscle strength and muscle quantity/quality associated with ageing or disease.","A muscle disease characterised primarily by low muscle strength, with muscle quantity/quality used to confirm severity.","Ageing, inactivity, malnutrition, chronic disease, inflammation and hospitalisation.","Weakness, slow gait, difficulty rising from chair, falls and reduced activity.","Case-finding with SARC-F or clinical suspicion; grip strength/chair stand, muscle mass and physical performance assessment.","Rapid unexplained weakness, acute weight loss or systemic symptoms requires medical investigation.","Progressive resistance exercise, adequate protein/energy intake with dietetic input and treatment of underlying causes.","Individualised progressive resistance plus balance and aerobic activity; practise transfers and daily tasks.","Adjust for frailty, comorbidities, nutrition and recovery; monitor pain and falls risk.","SARC-F, grip strength, 5-times sit-to-stand, gait speed and SPPB.","Grip dynamometry and chair-stand performance support assessment.","Cachexia, neurological disease, arthritis, endocrine disease and deconditioning.","Falls, fractures, disability and loss of independence."]
];
function buildTopic(t){
 const [id,title,system,summary,definition,causes,signs,assessment,redFlags,management,rehabPlan,precautions,outcomeMeasures,specialTests,differentials,complications]=t;
 return {id,title,system,summary,definition,causes,signs,assessment,redFlags,management,rehabPlan,precautions,outcomeMeasures,specialTests,differentials,complications,images:[],notes:"",cards:[],bookmarked:false,created:Date.now()};
}
function addMoreTopics(){
 const existing=new Set(db.conditions.map(c=>c.id));
 const added=MORE_TOPICS.filter(t=>!existing.has(t[0])).map(buildTopic);
 if(!added.length){toast("All additional topics are already in your library");return}
 db.conditions.push(...added);save();render();toast(added.length+" additional topics added");
}

function addStarterChapters(){
 const existing=new Set(db.conditions.map(c=>c.id));
 const added=STARTER_CHAPTERS.filter(c=>!existing.has(c.id)).map(c=>({...c,images:[],notes:"",cards:[],bookmarked:false,created:Date.now()}));
 if(!added.length){toast("All starter chapters are already in your library");return}
 db.conditions.push(...added);save();render();toast(added.length+" study chapters added");
}

function openCondition(id){activeId=id;render()}
function newCondition(){const id="c"+Date.now();db.conditions.unshift({id,title:"",system:"Musculoskeletal",summary:"",definition:"",causes:"",signs:"",assessment:"",management:"",complications:"",notes:"",images:[],cards:[],bookmarked:false});save();activeId=id;render()}
const fields=[["definition","Definition"],["causes","Causes & risk factors"],["signs","Signs & symptoms"],["assessment","Assessment & investigations"],["redFlags","Red flags & urgent referral"],["differentials","Differential diagnosis"],["specialTests","Special tests & clinical reasoning"],["outcomeMeasures","Outcome measures"],["management","Management & physiotherapy"],["rehabPlan","Rehabilitation plan / progression"],["precautions","Precautions & contraindications"],["complications","Complications"],["evidence","Evidence notes & guideline references"]];
function renderEditor(root){let c=db.conditions.find(x=>x.id===activeId);if(!c){activeId=null;return render()}root.innerHTML=`<div class="page-title"><button class="back" id="goBack">←</button><div><h1>${esc(c.title||"New condition")}</h1><p>YOUR PERSONAL CONDITION CHAPTER · EDITABLE NOTES</p></div><span style="margin-left:auto"></span><button class="btn secondary" id="bookmarkBtn">${c.bookmarked?"★ Saved":"☆ Bookmark"}</button><button class="btn" id="saveBtn">Save chapter</button></div>
<div class="editor-layout"><div class="paper-panel">
<div class="editor-field"><label>CONDITION NAME</label><input class="large-title" id="title" placeholder="e.g. Rotator cuff tendinopathy" value="${esc(c.title)}"></div>
<div class="editor-field"><label>BODY SYSTEM</label><select id="system">${SYSTEMS.map(s=>`<option ${c.system===s.name?"selected":""}>${s.name}</option>`).join("")}</select></div>
<div class="editor-field"><label>QUICK OVERVIEW</label><textarea id="summary" placeholder="A short description to help you remember this condition...">${esc(c.summary)}</textarea></div>
<div class="separator"></div><div class="section-head"><h2>Condition notes</h2><span class="eyebrow">YOUR TEXTBOOK</span></div>
${fields.map(([key,label])=>`<div class="editor-field"><label>${label.toUpperCase()}</label><textarea data-field="${key}" placeholder="Write, paste or build your notes here...">${esc(c[key]||"")}</textarea></div>`).join("")}
<div class="editor-field"><label>MY PERSONAL NOTES</label><div class="editor-toolbar"><button class="tool-chip" data-format="bold"><b>B</b></button><button class="tool-chip" data-format="italic"><i>I</i></button><button class="tool-chip" data-format="insertUnorderedList">• List</button></div><div class="rich-editor" id="personalNotes" contenteditable="true" data-placeholder="Your own explanations, mnemonics, lecture notes and clinical pearls...">${c.notes||""}</div></div>
<div class="separator"></div><div class="section-head"><h2>Visual library</h2><button class="btn secondary" id="addImages">＋ Add images</button></div><p style="font-size:11px;color:#8a958e;margin-top:-7px">Upload images or paste a copied image (Ctrl/Cmd + V) while on this page.</p><div class="media-grid" id="mediaGrid">${(c.images||[]).map((src,i)=>`<div class="media-item"><img src="${src}" alt="Study image ${i+1}"><button data-remove-image="${i}">×</button></div>`).join("")}</div><div class="separator"></div>
<div class="section-head"><h2>Flashcards for this condition</h2><button class="btn secondary" id="addCard">＋ Create card</button></div><div id="cardList">${(c.cards||[]).map((card,i)=>`<div class="side-panel"><b style="font-size:12px">${esc(card.q)}</b><p>${esc(card.a)}</p><button class="text-button" data-remove-card="${i}">Remove</button></div>`).join("")||'<p style="font-size:11px;color:#89948d">No cards yet. Turn your notes into quick recall questions.</p>'}</div>
</div><aside><div class="side-panel"><h3>Chapter tools</h3><button class="btn secondary" style="width:100%;margin-bottom:8px" id="drawForCondition">✎ Open sketchbook</button><button class="btn ghost" style="width:100%" id="deleteCondition">Delete condition</button><p>Your changes are stored in this browser. Export a backup regularly to keep a copy.</p></div><div class="side-panel"><h3>Study checklist</h3><p>Use this as a guide when building a complete condition chapter.</p>${["Definition","Causes & risk factors","Signs & symptoms","Assessment","Management","Complications","Visual notes","Flashcards"].map(x=>`<div style="font-size:11px;margin:9px 0;color:#66746c">□ ${x}</div>`).join("")}</div><div class="notice">Learning note: Use trusted clinical references and local guidelines to verify medical information. This atlas is for study, not diagnosis or treatment decisions.</div></aside></div>`;
const get=()=>{c.title=document.getElementById("title").value;c.system=document.getElementById("system").value;c.summary=document.getElementById("summary").value;fields.forEach(([k])=>c[k]=root.querySelector('[data-field="'+k+'"]').value);c.notes=document.getElementById("personalNotes").innerHTML};
document.getElementById("saveBtn").onclick=()=>{get();save();toast("Chapter saved")};document.getElementById("goBack").onclick=()=>{get();save();activeId=null;render()};document.getElementById("bookmarkBtn").onclick=()=>{c.bookmarked=!c.bookmarked;save();renderEditor(root)};document.getElementById("addImages").onclick=()=>document.getElementById("imageInput").click();document.getElementById("addCard").onclick=()=>{get();const q=prompt("Question / front of card:");if(!q)return;const a=prompt("Answer / back of card:");if(a){c.cards.push({q,a});save();renderEditor(root)}};document.getElementById("deleteCondition").onclick=()=>{if(confirm("Delete this condition and its notes?")){db.conditions=db.conditions.filter(x=>x.id!==c.id);save();activeId=null;render()}};document.getElementById("drawForCondition").onclick=()=>{get();save();view="canvas";activeId=null;render()};root.querySelectorAll("[data-format]").forEach(b=>b.onclick=()=>{document.execCommand(b.dataset.format,false,null)});root.querySelectorAll("[data-remove-image]").forEach(b=>b.onclick=()=>{c.images.splice(+b.dataset.removeImage,1);save();renderEditor(root)});root.querySelectorAll("[data-remove-card]").forEach(b=>b.onclick=()=>{c.cards.splice(+b.dataset.removeCard,1);save();renderEditor(root)});root.querySelector("#personalNotes").addEventListener("input",()=>{c.notes=root.querySelector("#personalNotes").innerHTML;save()})}
document.getElementById("imageInput").addEventListener("change",async e=>{if(!activeId)return;const c=db.conditions.find(x=>x.id===activeId);for(const f of e.target.files){if(!f.type.startsWith("image/"))continue;const data=await compressImage(f);c.images.push(data)}save();renderEditor(document.getElementById("content"));e.target.value=""});
function compressImage(file){return new Promise(resolve=>{const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{const scale=Math.min(1,1400/Math.max(img.width,img.height));const cv=document.createElement("canvas");cv.width=img.width*scale;cv.height=img.height*scale;cv.getContext("2d").drawImage(img,0,0,cv.width,cv.height);resolve(cv.toDataURL("image/jpeg",.82))};img.src=r.result};r.readAsDataURL(file)})}
document.addEventListener("paste",async e=>{if(!activeId)return;const file=[...(e.clipboardData?.items||[])].find(x=>x.type.startsWith("image/"))?.getAsFile();if(!file)return;e.preventDefault();const c=db.conditions.find(x=>x.id===activeId);c.images.push(await compressImage(file));save();renderEditor(document.getElementById("content"));toast("Image added to your visual library")});
function allCards(){return db.conditions.flatMap(c=>(c.cards||[]).map((card,i)=>({...card,condition:c.title,conditionId:c.id,index:i})))}
function renderFlash(root){flashDeck=allCards();if(!flashDeck.length){root.innerHTML='<div class="hero"><div><div class="eyebrow">ACTIVE RECALL</div><h1>Flashcard studio</h1><p>Turn your condition notes into questions you can practise anywhere.</p></div></div><div class="empty"><b>Your deck is waiting.</b>Create flashcards inside any condition chapter to start a revision session.</div>';return}flashIndex=flashIndex%flashDeck.length;const c=flashDeck[flashIndex];root.innerHTML=`<div class="hero"><div><div class="eyebrow">ACTIVE RECALL · STUDY MODE</div><h1>Flashcard studio</h1><p>Retrieve what you know. Strengthen what you don't.</p></div><span class="tag">${flashDeck.length} CARDS IN YOUR DECK</span></div><div class="flash-wrap"><div style="display:flex;justify-content:space-between;color:#89948d;font-size:10px"><span>YOUR REVISION SESSION</span><span>${flashIndex+1} / ${flashDeck.length}</span></div><div class="flash-progress"><span style="width:${(flashIndex+1)/flashDeck.length*100}%"></span></div><div class="flash-card" id="flashCard"><div class="flash-label">${flashRevealed?"THE ANSWER":"QUESTION"}</div><h2>${esc(flashRevealed?c.a:c.q)}</h2><p>${flashRevealed?"From: "+esc(c.condition):"Think of your answer, then reveal the back of the card."}</p><span class="tag">${esc(c.condition)}</span></div><div class="flash-actions"><button class="btn ghost" id="prevCard">← Previous</button><button class="btn" id="revealCard">${flashRevealed?"Show question":"Reveal answer"}</button><button class="btn ghost" id="nextCard">Next →</button></div></div>`;document.getElementById("flashCard").onclick=()=>{flashRevealed=!flashRevealed;renderFlash(root)};document.getElementById("revealCard").onclick=()=>{flashRevealed=!flashRevealed;renderFlash(root)};document.getElementById("prevCard").onclick=()=>{flashIndex=(flashIndex-1+flashDeck.length)%flashDeck.length;flashRevealed=false;renderFlash(root)};document.getElementById("nextCard").onclick=()=>{flashIndex=(flashIndex+1)%flashDeck.length;flashRevealed=false;renderFlash(root)}}

const ARTICLE_FIELDS=[
["authors","Authors"],["year","Publication year"],["journal","Journal / source"],["doi","DOI or URL"],["question","Research question (PICO/PEO)"],["design","Study design"],["sample","Participants, setting & sample size"],["intervention","Intervention / exposure & comparator"],["outcomes","Primary and secondary outcomes"],["results","Main results (include effect sizes / CI if reported)"],["strengths","Strengths"],["limitations","Limitations & sources of bias"],["validity","Validity, reliability & risk of bias"],["applicability","Clinical applicability to physiotherapy"],["takeaways","Practice implications / key learning"],["reflection","Your critique and unanswered questions"]
];
function renderArticles(root){
 const articles=db.articles||[];
 root.innerHTML='<div class="hero"><div><div class="eyebrow">EVIDENCE-INFORMED PRACTICE</div><h1>Articles & critical appraisal</h1><p>Build a journal club library. Read actively, question methods and connect evidence to patient-centred physiotherapy.</p></div><div class="hero-art">📖</div></div>'+
 '<div class="article-guide"><b>How to critique an article:</b> identify the question and design; assess sampling, allocation/blinding or confounding; inspect outcome measures, effect sizes and confidence intervals; consider missing data and limitations; then judge whether the findings apply to your patient group and setting. Use a design-appropriate checklist such as CASP, PEDro, CONSORT, STROBE or PRISMA. A checklist supports—not replaces—your reasoning.</div>'+
 '<div class="section-head"><h2>Your article library · '+articles.length+'</h2><button class="btn" id="newArticle">＋ Add article critique</button></div>'+
 (articles.length?'<div class="article-grid">'+articles.map((a,i)=>'<article class="article-card"><span class="tag">'+esc(a.design||"Study design not entered")+'</span><h3>'+esc(a.title||"Untitled article")+'</h3><p>'+esc([a.authors,a.year,a.journal].filter(Boolean).join(" · "))+'</p><p>'+esc(a.question||"Add the research question and your critical appraisal.")+'</p><div class="article-meta"><span>'+esc(a.year||"Year n/a")+'</span><span>'+esc(a.status||"To appraise")+'</span></div><div class="toolbar-row"><button class="btn secondary" data-edit-article="'+i+'">Open critique</button><button class="btn ghost" data-delete-article="'+i+'">Delete</button></div></article>').join("")+'</div>':'<div class="empty"><b>Your evidence library is ready.</b>Add a paper to record its methods, results, strengths, limitations and relevance to practice.</div>');
 document.getElementById("newArticle").onclick=()=>editArticle(-1);
 root.querySelectorAll("[data-edit-article]").forEach(b=>b.onclick=()=>editArticle(+b.dataset.editArticle));
 root.querySelectorAll("[data-delete-article]").forEach(b=>b.onclick=()=>{if(confirm("Delete this article critique?")){db.articles.splice(+b.dataset.deleteArticle,1);save();renderArticles(root)}});
}
function editArticle(index){
 const a=index<0?{title:"",authors:"",year:"",journal:"",doi:"",design:"",status:"To appraise"}:{...db.articles[index]};
 const root=document.getElementById("content");
 const input=(key,label)=>'<div class="article-field"><label>'+label.toUpperCase()+'</label><input data-article="'+key+'" value="'+esc(a[key]||"")+'" placeholder="'+label+'"></div>';
 const area=(key,label)=>'<div class="article-field"><label>'+label.toUpperCase()+'</label><textarea data-article="'+key+'" placeholder="Write your appraisal...">'+esc(a[key]||"")+'</textarea></div>';
 root.innerHTML='<div class="page-title"><button class="back" id="articleBack">←</button><div><h1>'+(index<0?"New article critique":esc(a.title||"Article critique"))+'</h1><p>STRUCTURED CRITICAL APPRAISAL WORKSHEET</p></div></div><div class="paper-panel">'+
 '<div class="article-field"><label>ARTICLE TITLE</label><input data-article="title" value="'+esc(a.title||"")+'" placeholder="Full article title"></div>'+
 '<div class="article-form-grid">'+input("authors","Authors") + input("year","Publication year") + input("journal","Journal / source") + input("doi","DOI or URL")+'</div>'+
 '<div class="article-field"><label>APPRAISAL STATUS</label><select data-article="status"><option '+(a.status==="To appraise"?"selected":"")+' >To appraise</option><option '+(a.status==="In progress"?"selected":"")+' >In progress</option><option '+(a.status==="Completed"?"selected":"")+' >Completed</option></select></div>'+
 '<div class="section-head"><h2>Research methods & findings</h2></div>'+ARTICLE_FIELDS.slice(4,10).map(x=>area(x[0],x[1])).join("")+
 '<div class="section-head"><h2>Critical appraisal</h2></div>'+ARTICLE_FIELDS.slice(10).map(x=>area(x[0],x[1])).join("")+
 '<div class="toolbar-row"><button class="btn" id="saveArticle">Save critique</button><button class="btn ghost" id="cancelArticle">Cancel</button></div></div>';
 const collect=()=>{root.querySelectorAll("[data-article]").forEach(el=>a[el.dataset.article]=el.value);a.updated=Date.now()};
 document.getElementById("saveArticle").onclick=()=>{collect();if(!a.title.trim()){toast("Please add the article title");return}if(index<0)db.articles.unshift(a);else db.articles[index]=a;save();renderArticles(root);toast("Article critique saved")};
 document.getElementById("cancelArticle").onclick=()=>renderArticles(root);
 document.getElementById("articleBack").onclick=()=>renderArticles(root);
}

function renderSketch(root){root.innerHTML=`<div class="hero"><div><div class="eyebrow">THINK IN PICTURES</div><h1>Your sketchbook.</h1><p>Draw anatomy, map a mechanism, or sketch out a treatment concept.</p></div><button class="btn" id="saveSketch">Save sketch</button></div><div class="editor-layout"><div class="paper-panel"><div class="canvas-tools"><label class="field-label">PEN</label><input type="color" id="penColor" value="#285f50"><label class="field-label">SIZE</label><input type="range" id="penSize" min="1" max="24" value="3"><button class="tool-chip" id="eraser">Eraser</button><button class="tool-chip" id="undo">Undo</button><button class="tool-chip" id="clearCanvas">Clear</button></div><div class="canvas-wrap"><canvas id="drawingCanvas" width="1100" height="520"></canvas></div><div class="editor-field" style="margin-top:15px"><label>SKETCH TITLE</label><input id="sketchTitle" placeholder="e.g. Knee joint — ACL anatomy"></div></div><aside><div class="side-panel"><h3>Your visual thinking space</h3><p>Use a mouse, trackpad, stylus or touchscreen. Your drawing can be saved as an image in your browser.</p></div><div class="side-panel"><h3>Saved sketches</h3><div id="savedSketches">${(db.sketches||[]).map((s,i)=>`<div style="margin-bottom:12px"><img src="${s.image}" style="width:100%;border-radius:7px"><p>${esc(s.title)}</p><button class="text-button" data-delete-sketch="${i}">Delete</button></div>`).join("")||'<p>No saved sketches yet.</p>'}</div></div></aside></div>`;
const cv=document.getElementById("drawingCanvas");ctx=cv.getContext("2d");ctx.lineCap="round";ctx.lineJoin="round";let last=null;function pos(e){const r=cv.getBoundingClientRect();return{x:(e.clientX-r.left)*cv.width/r.width,y:(e.clientY-r.top)*cv.height/r.height}}function start(e){drawing=true;last=pos(e);canvasHistory.push(cv.toDataURL())}function move(e){if(!drawing)return;const p=pos(e);ctx.strokeStyle=document.getElementById("eraser").classList.contains("selected")?"#ffffff":document.getElementById("penColor").value;ctx.lineWidth=+document.getElementById("penSize").value*(cv.width/cv.clientWidth);ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.stroke();last=p}function stop(){drawing=false}cv.onpointerdown=e=>{cv.setPointerCapture(e.pointerId);start(e)};cv.onpointermove=move;cv.onpointerup=stop;cv.onpointercancel=stop;document.getElementById("eraser").onclick=e=>e.target.classList.toggle("selected");document.getElementById("undo").onclick=()=>{const img=new Image();img.onload=()=>{ctx.clearRect(0,0,cv.width,cv.height);ctx.drawImage(img,0,0)};if(canvasHistory.length)img.src=canvasHistory.pop()};document.getElementById("clearCanvas").onclick=()=>{canvasHistory.push(cv.toDataURL());ctx.clearRect(0,0,cv.width,cv.height)};document.getElementById("saveSketch").onclick=()=>{db.sketches.unshift({title:document.getElementById("sketchTitle").value||"Untitled sketch",image:cv.toDataURL("image/png")});save();toast("Sketch saved");renderSketch(root)};root.querySelectorAll("[data-delete-sketch]").forEach(b=>b.onclick=()=>{db.sketches.splice(+b.dataset.deleteSketch,1);save();renderSketch(root)})}
function renderSettings(root){root.innerHTML=`<div class="hero"><div><div class="eyebrow">YOUR SPACE, YOUR WAY</div><h1>Settings & backup</h1><p>Keep your personal textbook organised and safe.</p></div><div class="hero-art">✦</div></div><div class="settings-grid"><div class="tool-panel"><h3>Export your textbook</h3><p style="font-size:11px;color:#849087;line-height:1.6">Download your conditions, notes, flashcards and saved sketches as a JSON backup file.</p><button class="btn" id="exportData">↓ Export my atlas</button></div><div class="tool-panel"><h3>Restore a backup</h3><p style="font-size:11px;color:#849087;line-height:1.6">Import a previous Physio Atlas backup. This replaces the data currently stored in this browser.</p><button class="btn secondary" id="importData">↑ Import backup</button></div><div class="tool-panel"><h3>Your study library</h3><p style="font-size:11px;color:#849087">Conditions saved: <b>${db.conditions.length}</b><br>Flashcards: <b>${allCards().length}</b><br>Sketches: <b>${(db.sketches||[]).length}</b></p></div><div class="tool-panel"><h3>About Physio Atlas</h3><p style="font-size:11px;color:#849087;line-height:1.7">A personal, visual learning space for physiotherapy and medical study. Your content is stored locally in this browser. Images and sketches can use significant browser storage.</p></div></div><div class="notice" style="margin-top:16px">Privacy: Your notes stay in this browser unless you export or share a backup. Clearing browser site data may erase your library. Export backups regularly. Do not store patient-identifiable information here.</div>`;document.getElementById("exportData").onclick=()=>{const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:"application/json"}));a.download="physio-atlas-backup.json";a.click();URL.revokeObjectURL(a.href)};document.getElementById("importData").onclick=()=>document.getElementById("importInput").click()}
document.getElementById("importInput").onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const d=JSON.parse(await f.text());if(!Array.isArray(d.conditions))throw Error();if(confirm("Replace your current atlas with this backup?")){db=d;save();render();toast("Backup restored")}}catch{toast("That backup file could not be read")}e.target.value=""};
document.querySelectorAll(".nav-item[data-view]").forEach(b=>b.onclick=()=>setView(b.dataset.view));document.getElementById("newCondition").onclick=newCondition;document.getElementById("mobileMenu").onclick=()=>document.getElementById("sidebar").classList.toggle("open");document.getElementById("searchInput").oninput=e=>{search=e.target.value;if(view!=="library")setView("library");else render()};document.addEventListener("keydown",e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();document.getElementById("searchInput").focus()}if(e.key==="Escape"){document.getElementById("sidebar").classList.remove("open")}});
systemNav();updateStats();render();